RRB.load({"id": "ntpc-full-8", "exam": "ntpc", "label": "NTPC UG full mock 8 (100 Q)", "questions": [{"s": "General Awareness", "t": "History", "q": "The system of 'Subsidiary Alliance' was introduced by:", "o": ["Lord Cornwallis", "Lord Wellesley", "Warren Hastings", "Lord Hastings"], "a": 1, "e": "Lord Wellesley (1798–1805) used the Subsidiary Alliance; Hyderabad was the first state to accept it (1798).", "qh": "'सहायक संधि' की व्यवस्था किसने शुरू की?", "oh": ["लॉर्ड कॉर्नवालिस", "लॉर्ड वेलेज़ली", "वॉरेन हेस्टिंग्स", "लॉर्ड हेस्टिंग्स"], "eh": "लॉर्ड वेलेज़ली (1798–1805) ने सहायक संधि लागू की; हैदराबाद इसे मानने वाला पहला राज्य (1798) था।", "level": "medium"}, {"s": "General Awareness", "t": "General Science", "q": "Beriberi is caused by the deficiency of:", "o": ["Vitamin B12", "Vitamin C", "Vitamin D", "Vitamin B1 (thiamine)"], "a": 3, "e": "Lack of thiamine (B1) causes beriberi, affecting nerves and heart.", "qh": "बेरी-बेरी किसकी कमी से होता है?", "oh": ["विटामिन B12", "विटामिन C", "विटामिन D", "विटामिन B1 (थायमिन)"], "eh": "थायमिन (B1) की कमी से बेरी-बेरी होता है, जो नसों और हृदय पर असर डालता है।", "level": "easy"}, {"s": "General Awareness", "t": "Current Affairs", "q": "Who took over as the 29th Chief of the Air Staff of the Indian Air Force on 31 October 2026?", "o": ["Air Chief Marshal Ashutosh Dixit", "Air Marshal Narmdeshwar Tiwari", "Air Marshal S. P. Dharkar", "Air Marshal Jeetendra Mishra"], "a": 0, "e": "Air Chief Marshal Ashutosh Dixit became the 29th Chief of the Air Staff on 31 October 2026, succeeding Air Chief Marshal A. P. Singh.", "qh": "31 अक्टूबर 2026 को भारतीय वायुसेना के 29वें वायुसेना प्रमुख का पद किसने संभाला?", "oh": ["एयर चीफ़ मार्शल आशुतोष दीक्षित", "एयर मार्शल नर्मदेश्वर तिवारी", "एयर मार्शल एस. पी. धारकर", "एयर मार्शल जीतेंद्र मिश्रा"], "eh": "एयर चीफ़ मार्शल आशुतोष दीक्षित 31 अक्टूबर 2026 को एयर चीफ़ मार्शल ए. पी. सिंह के बाद 29वें वायुसेना प्रमुख बने।", "level": "medium"}, {"s": "General Awareness", "t": "Sports", "q": "Who were India's flag-bearers at the closing ceremony of the 2026 Asian Para Games in Aichi-Nagoya?", "o": ["Sumit Antil and Bhagyashri Jadhav", "Avani Lekhara and Praveen Kumar", "Mona Agarwal and Nishad Kumar", "Sheetal Devi and Harvinder Singh"], "a": 2, "e": "Double gold medallists Mona Agarwal (shooting) and Nishad Kumar (high jump) carried the flag at the closing ceremony. The Asian Para Games were held in Aichi-Nagoya, Japan, from 18 to 24 October 2026; India won a record 114 medals (30 gold, 35 silver, 49 bronze).", "qh": "2026 के आइची-नागोया एशियाई पैरा खेलों के समापन समारोह में भारत के ध्वजवाहक कौन थे?", "oh": ["सुमित अंतिल और भाग्यश्री जाधव", "अवनि लेखरा और प्रवीण कुमार", "मोना अग्रवाल और निषाद कुमार", "शीतल देवी और हरविंदर सिंह"], "eh": "दोहरे स्वर्ण पदक विजेता मोना अग्रवाल (निशानेबाज़ी) और निषाद कुमार (ऊँची कूद) ध्वजवाहक बने। एशियाई पैरा खेल आइची-नागोया (जापान) में 18–24 अक्टूबर 2026 को हुए; भारत ने रिकॉर्ड 114 पदक (30 स्वर्ण, 35 रजत, 49 कांस्य) जीते।", "level": "medium"}, {"s": "General Awareness", "t": "Geography", "q": "Barren Island, India's only confirmed active volcano, is part of:", "o": ["Lakshadweep", "Gujarat coast", "Odisha coast", "Andaman and Nicobar Islands"], "a": 3, "e": "Barren Island lies in the Andaman Sea, about 135 km north-east of Port Blair.", "qh": "भारत का एकमात्र पुष्ट सक्रिय ज्वालामुखी, बैरन द्वीप, कहाँ है?", "oh": ["लक्षद्वीप", "गुजरात तट", "ओडिशा तट", "अंडमान और निकोबार द्वीप समूह"], "eh": "बैरन द्वीप अंडमान सागर में पोर्ट ब्लेयर से लगभग 135 km उत्तर-पूर्व में है।", "level": "medium"}, {"s": "General Awareness", "t": "Polity", "q": "Which Article states that the official language of the Union shall be Hindi in Devanagari script?", "o": ["Article 351", "Article 345", "Article 348", "Article 343"], "a": 3, "e": "Article 343(1) makes Hindi in Devanagari script the official language of the Union.", "qh": "कौन-सा अनुच्छेद कहता है कि संघ की राजभाषा देवनागरी लिपि में हिंदी होगी?", "oh": ["अनुच्छेद 351", "अनुच्छेद 345", "अनुच्छेद 348", "अनुच्छेद 343"], "eh": "अनुच्छेद 343(1) देवनागरी लिपि में हिंदी को संघ की राजभाषा बनाता है।", "level": "tough"}, {"s": "General Awareness", "t": "Current Affairs", "q": "Who was sworn in as the President of Colombia on 7 August 2026?", "o": ["Gustavo Petro", "Iván Duque", "Abelardo de la Espriella", "Vicky Dávila"], "a": 2, "e": "Abelardo de la Espriella took office as President of Colombia on 7 August 2026, succeeding Gustavo Petro.", "qh": "7 अगस्त 2026 को कोलंबिया के राष्ट्रपति पद की शपथ किसने ली?", "oh": ["गुस्तावो पेट्रो", "इवान दुके", "अबेलार्डो दे ला एस्प्रिएला", "विकी दाविला"], "eh": "अबेलार्डो दे ला एस्प्रिएला ने 7 अगस्त 2026 को गुस्तावो पेट्रो के बाद कोलंबिया के राष्ट्रपति का पद संभाला।", "level": "medium"}, {"s": "General Awareness", "t": "History", "q": "Dholavira, a major Harappan city, is located in which state?", "o": ["Gujarat", "Rajasthan", "Haryana", "Punjab"], "a": 0, "e": "Dholavira is on Khadir Bet island in the Rann of Kutch, Gujarat.", "qh": "हड़प्पा सभ्यता का प्रमुख नगर धोलावीरा किस राज्य में है?", "oh": ["गुजरात", "राजस्थान", "हरियाणा", "पंजाब"], "eh": "धोलावीरा गुजरात के कच्छ के रण में खडीर बेट द्वीप पर है।", "level": "easy"}, {"s": "General Awareness", "t": "Science & Tech", "q": "'Kusha', which DRDO flight-tested for the first time in July 2026, is India's indigenous:", "o": ["Anti-tank guided missile", "Intercontinental ballistic missile", "Submarine-launched cruise missile", "Long-range surface-to-air missile (air defence) system"], "a": 3, "e": "Project Kusha is DRDO's long-range surface-to-air missile system for air defence; its first flight test took place on 23 July 2026.", "qh": "'कुशा', जिसका DRDO ने जुलाई 2026 में पहली बार उड़ान परीक्षण किया, भारत की कौन-सी स्वदेशी प्रणाली है?", "oh": ["टैंक-रोधी निर्देशित मिसाइल", "अंतरमहाद्वीपीय बैलिस्टिक मिसाइल", "पनडुब्बी से दागी जाने वाली क्रूज़ मिसाइल", "लंबी दूरी की सतह-से-हवा मिसाइल (वायु रक्षा) प्रणाली"], "eh": "प्रोजेक्ट कुशा DRDO की वायु रक्षा के लिए लंबी दूरी की सतह-से-हवा मिसाइल प्रणाली है; इसका पहला उड़ान परीक्षण 23 जुलाई 2026 को हुआ।", "level": "tough"}, {"s": "General Awareness", "t": "Art & Culture", "q": "Guru Kelucharan Mohapatra is famous for which classical dance?", "o": ["Kathakali", "Kuchipudi", "Odissi", "Manipuri"], "a": 2, "e": "Kelucharan Mohapatra (1926–2004) revived and popularised Odissi.", "qh": "गुरु केलुचरण महापात्र किस शास्त्रीय नृत्य के लिए प्रसिद्ध हैं?", "oh": ["कथकली", "कुचिपुड़ी", "ओडिसी", "मणिपुरी"], "eh": "केलुचरण महापात्र (1926–2004) ने ओडिसी को फिर से जीवित और लोकप्रिय किया।", "level": "medium"}, {"s": "General Awareness", "t": "General Science", "q": "Which instrument measures the relative humidity of air?", "o": ["Barometer", "Hygrometer", "Anemometer", "Lactometer"], "a": 1, "e": "A hygrometer measures humidity; barometer – pressure, anemometer – wind speed, lactometer – milk density.", "qh": "हवा की आपेक्षिक आर्द्रता किस यंत्र से मापी जाती है?", "oh": ["बैरोमीटर", "हाइग्रोमीटर", "एनीमोमीटर", "लैक्टोमीटर"], "eh": "हाइग्रोमीटर आर्द्रता मापता है; बैरोमीटर – दाब, एनीमोमीटर – हवा की गति, लैक्टोमीटर – दूध का घनत्व।", "level": "medium"}, {"s": "General Awareness", "t": "General Science", "q": "The Contact Process is used for the industrial manufacture of:", "o": ["Sulphuric acid", "Ammonia", "Nitric acid", "Sodium hydroxide"], "a": 0, "e": "In the Contact Process SO₂ is oxidised to SO₃ over V₂O₅ and turned into H₂SO₄. (Ammonia – Haber process; nitric acid – Ostwald process.)", "qh": "संपर्क विधि (Contact Process) से किसका औद्योगिक उत्पादन होता है?", "oh": ["सल्फ़्यूरिक अम्ल", "अमोनिया", "नाइट्रिक अम्ल", "सोडियम हाइड्रॉक्साइड"], "eh": "संपर्क विधि में SO₂ को V₂O₅ पर SO₃ में बदलकर H₂SO₄ बनाया जाता है। (अमोनिया – हैबर विधि; नाइट्रिक अम्ल – ओस्टवाल्ड विधि।)", "level": "tough"}, {"s": "General Awareness", "t": "History", "q": "In which year did the Cripps Mission come to India?", "o": ["1939", "1945", "1946", "1942"], "a": 3, "e": "Sir Stafford Cripps came in March 1942 offering dominion status after the war; the Congress rejected it.", "qh": "क्रिप्स मिशन भारत किस वर्ष आया?", "oh": ["1939", "1945", "1946", "1942"], "eh": "सर स्टैफ़र्ड क्रिप्स मार्च 1942 में युद्ध के बाद डोमिनियन दर्जे का प्रस्ताव लेकर आए; कांग्रेस ने इसे ठुकरा दिया।", "level": "tough"}, {"s": "General Awareness", "t": "Polity", "q": "The Union List, State List and Concurrent List are given in which Schedule of the Constitution?", "o": ["Seventh Schedule", "Fifth Schedule", "Ninth Schedule", "Eleventh Schedule"], "a": 0, "e": "The Seventh Schedule divides legislative subjects between the Union and the States.", "qh": "संघ सूची, राज्य सूची और समवर्ती सूची संविधान की किस अनुसूची में हैं?", "oh": ["सातवीं अनुसूची", "पाँचवीं अनुसूची", "नौवीं अनुसूची", "ग्यारहवीं अनुसूची"], "eh": "सातवीं अनुसूची विधायी विषयों को संघ और राज्यों के बीच बाँटती है।", "level": "medium"}, {"s": "General Awareness", "t": "Static GK", "q": "National Youth Day (12 January) marks the birth anniversary of:", "o": ["Swami Vivekananda", "Subhas Chandra Bose", "Rabindranath Tagore", "Dayananda Saraswati"], "a": 0, "e": "Swami Vivekananda was born on 12 January 1863.", "qh": "राष्ट्रीय युवा दिवस (12 जनवरी) किसकी जयंती पर मनाया जाता है?", "oh": ["स्वामी विवेकानंद", "सुभाष चंद्र बोस", "रवींद्रनाथ टैगोर", "दयानंद सरस्वती"], "eh": "स्वामी विवेकानंद का जन्म 12 जनवरी 1863 को हुआ था।", "level": "easy"}, {"s": "General Awareness", "t": "Geography", "q": "Indian Standard Time (IST) is based on which longitude?", "o": ["77°30′ E", "82°30′ E", "88°30′ E", "68°07′ E"], "a": 1, "e": "IST is fixed on 82°30′ E, which passes near Mirzapur (Uttar Pradesh); it is 5 h 30 min ahead of GMT.", "qh": "भारतीय मानक समय (IST) किस देशांतर पर आधारित है?", "oh": ["77°30′ पूर्व", "82°30′ पूर्व", "88°30′ पूर्व", "68°07′ पूर्व"], "eh": "IST 82°30′ पूर्व देशांतर पर तय है, जो मिर्ज़ापुर (उत्तर प्रदेश) के पास से गुज़रता है; यह GMT से 5 घंटे 30 मिनट आगे है।", "level": "easy"}, {"s": "General Awareness", "t": "Computer", "q": "A fake e-mail that tricks a user into revealing passwords or bank details is an example of:", "o": ["Firewall", "Encryption", "Formatting", "Phishing"], "a": 3, "e": "Phishing uses fake messages or websites to steal sensitive information.", "qh": "नकली ई-मेल जो उपयोगकर्ता को धोखे से पासवर्ड या बैंक विवरण बताने पर मजबूर करे, किसका उदाहरण है?", "oh": ["फ़ायरवॉल", "एन्क्रिप्शन", "फ़ॉर्मेटिंग", "फ़िशिंग"], "eh": "फ़िशिंग में नकली संदेश या वेबसाइट से संवेदनशील जानकारी चुराई जाती है।", "level": "easy"}, {"s": "General Awareness", "t": "History", "q": "The Kakori train action of 1925 was carried out by members of which organisation?", "o": ["Ghadar Party", "Anushilan Samiti", "Hindustan Republican Association", "Abhinav Bharat"], "a": 2, "e": "Ram Prasad Bismil, Ashfaqulla Khan and others of the Hindustan Republican Association looted a train carrying government money near Kakori (Lucknow) in August 1925.", "qh": "1925 की काकोरी ट्रेन कार्रवाई किस संगठन के सदस्यों ने की थी?", "oh": ["ग़दर पार्टी", "अनुशीलन समिति", "हिंदुस्तान रिपब्लिकन एसोसिएशन", "अभिनव भारत"], "eh": "हिंदुस्तान रिपब्लिकन एसोसिएशन के राम प्रसाद बिस्मिल, अशफ़ाक़ उल्ला ख़ाँ आदि ने अगस्त 1925 में काकोरी (लखनऊ) के पास सरकारी ख़ज़ाना ले जा रही ट्रेन लूटी।", "level": "tough"}, {"s": "General Awareness", "t": "Economy", "q": "The 'Bombay Plan' of 1944 was prepared by:", "o": ["M. N. Roy", "Leading industrialists such as J. R. D. Tata and G. D. Birla", "Shriman Narayan", "The Planning Commission"], "a": 1, "e": "The Bombay Plan was drafted by eight industrialists. M. N. Roy prepared the People's Plan and Shriman Narayan the Gandhian Plan.", "qh": "1944 का 'बॉम्बे प्लान' किसने तैयार किया था?", "oh": ["एम. एन. रॉय ने", "जे. आर. डी. टाटा और जी. डी. बिड़ला जैसे प्रमुख उद्योगपतियों ने", "श्रीमन नारायण ने", "योजना आयोग ने"], "eh": "बॉम्बे प्लान आठ उद्योगपतियों ने बनाया था। एम. एन. रॉय ने 'पीपुल्स प्लान' और श्रीमन नारायण ने 'गांधीवादी योजना' बनाई।", "level": "tough"}, {"s": "General Awareness", "t": "Geography", "q": "Khetri in Rajasthan is well known for the mining of:", "o": ["Gold", "Copper", "Bauxite", "Manganese"], "a": 1, "e": "The Khetri copper belt (Jhunjhunu district) is worked by Hindustan Copper Limited.", "qh": "राजस्थान का खेतड़ी किसके खनन के लिए प्रसिद्ध है?", "oh": ["सोना", "तांबा", "बॉक्साइट", "मैंगनीज़"], "eh": "खेतड़ी ताम्र पट्टी (झुंझुनू ज़िला) में हिंदुस्तान कॉपर लिमिटेड खनन करता है।", "level": "tough"}, {"s": "General Awareness", "t": "Computer", "q": "Which program translates a whole high-level-language program into machine code before it is run?", "o": ["Interpreter", "Assembler", "Compiler", "Loader"], "a": 2, "e": "A compiler translates the entire program at once; an interpreter translates and runs line by line; an assembler converts assembly language.", "qh": "कौन-सा प्रोग्राम पूरे उच्च-स्तरीय भाषा के प्रोग्राम को चलाने से पहले मशीन कोड में बदल देता है?", "oh": ["इंटरप्रेटर", "असेंबलर", "कंपाइलर", "लोडर"], "eh": "कंपाइलर पूरा प्रोग्राम एक बार में बदलता है; इंटरप्रेटर लाइन-दर-लाइन बदलकर चलाता है; असेंबलर असेंबली भाषा बदलता है।", "level": "medium"}, {"s": "General Awareness", "t": "History", "q": "The Poona Pact of 1932 was signed between Mahatma Gandhi and:", "o": ["Muhammad Ali Jinnah", "Jawaharlal Nehru", "Tej Bahadur Sapru", "B. R. Ambedkar"], "a": 3, "e": "The Poona Pact (September 1932) replaced separate electorates for depressed classes with reserved seats in joint electorates.", "qh": "1932 का पूना समझौता महात्मा गांधी और किसके बीच हुआ?", "oh": ["मुहम्मद अली जिन्ना", "जवाहरलाल नेहरू", "तेज बहादुर सप्रू", "बी. आर. आंबेडकर"], "eh": "पूना समझौते (सितंबर 1932) में दलित वर्गों के लिए अलग निर्वाचक मंडल की जगह संयुक्त निर्वाचक मंडल में आरक्षित सीटें तय हुईं।", "level": "medium"}, {"s": "General Awareness", "t": "Polity", "q": "Who was the Chairman of the Drafting Committee of the Constituent Assembly?", "o": ["Rajendra Prasad", "B. R. Ambedkar", "Jawaharlal Nehru", "B. N. Rau"], "a": 1, "e": "Dr B. R. Ambedkar chaired the Drafting Committee; Rajendra Prasad was President of the Constituent Assembly and B. N. Rau its Constitutional Adviser.", "qh": "संविधान सभा की प्रारूप समिति के अध्यक्ष कौन थे?", "oh": ["राजेंद्र प्रसाद", "बी. आर. आंबेडकर", "जवाहरलाल नेहरू", "बी. एन. राउ"], "eh": "डॉ. बी. आर. आंबेडकर प्रारूप समिति के अध्यक्ष थे; राजेंद्र प्रसाद संविधान सभा के अध्यक्ष और बी. एन. राउ संवैधानिक सलाहकार थे।", "level": "easy"}, {"s": "General Awareness", "t": "Geography", "q": "Lonar Lake, formed by a meteorite impact, is in which state?", "o": ["Maharashtra", "Madhya Pradesh", "Karnataka", "Telangana"], "a": 0, "e": "Lonar crater lake is in Buldhana district, Maharashtra, in basalt rock.", "qh": "उल्कापिंड के टकराने से बनी लोनार झील किस राज्य में है?", "oh": ["महाराष्ट्र", "मध्य प्रदेश", "कर्नाटक", "तेलंगाना"], "eh": "लोनार क्रेटर झील महाराष्ट्र के बुलढाणा ज़िले में बेसाल्ट चट्टान में है।", "level": "tough"}, {"s": "General Awareness", "t": "History", "q": "The Vernacular Press Act of 1878 was passed during the tenure of which Viceroy?", "o": ["Lord Ripon", "Lord Curzon", "Lord Dufferin", "Lord Lytton"], "a": 3, "e": "Lord Lytton's Vernacular Press Act (1878) curbed Indian-language newspapers; Lord Ripon repealed it in 1882.", "qh": "1878 का वर्नाक्युलर प्रेस एक्ट किस वायसराय के कार्यकाल में पारित हुआ?", "oh": ["लॉर्ड रिपन", "लॉर्ड कर्ज़न", "लॉर्ड डफ़रिन", "लॉर्ड लिटन"], "eh": "लॉर्ड लिटन के वर्नाक्युलर प्रेस एक्ट (1878) ने भारतीय भाषाओं के अख़बारों पर रोक लगाई; लॉर्ड रिपन ने 1882 में इसे रद्द किया।", "level": "medium"}, {"s": "General Awareness", "t": "Economy", "q": "India's gross GST collection reached an all-time monthly high in April 2026. About how much was it?", "o": ["About ₹1.6 lakh crore", "Over ₹2.4 lakh crore", "About ₹1.9 lakh crore", "Over ₹3 lakh crore"], "a": 1, "e": "Gross GST collections hit a record of about ₹2.42 lakh crore in April 2026, the highest for any month since GST began in 2017.", "qh": "अप्रैल 2026 में भारत का सकल GST संग्रह अब तक के सबसे ऊँचे मासिक स्तर पर पहुँचा। यह लगभग कितना था?", "oh": ["लगभग ₹1.6 लाख करोड़", "₹2.4 लाख करोड़ से अधिक", "लगभग ₹1.9 लाख करोड़", "₹3 लाख करोड़ से अधिक"], "eh": "अप्रैल 2026 में सकल GST संग्रह लगभग ₹2.42 लाख करोड़ के रिकॉर्ड पर पहुँचा, जो 2017 में GST शुरू होने के बाद किसी भी महीने में सबसे ज़्यादा है।", "level": "medium"}, {"s": "General Awareness", "t": "Geography", "q": "Keoladeo National Park, famous for migratory birds, is in which state?", "o": ["Rajasthan", "Madhya Pradesh", "Gujarat", "Haryana"], "a": 0, "e": "Keoladeo (Bharatpur Bird Sanctuary), Rajasthan, is a UNESCO World Heritage Site.", "qh": "प्रवासी पक्षियों के लिए प्रसिद्ध केवलादेव राष्ट्रीय उद्यान किस राज्य में है?", "oh": ["राजस्थान", "मध्य प्रदेश", "गुजरात", "हरियाणा"], "eh": "केवलादेव (भरतपुर पक्षी विहार), राजस्थान, यूनेस्को विश्व धरोहर स्थल है।", "level": "medium"}, {"s": "General Awareness", "t": "Polity", "q": "Which Constitutional Amendment gave constitutional status to urban local bodies (municipalities)?", "o": ["73rd Amendment", "42nd Amendment", "74th Amendment", "86th Amendment"], "a": 2, "e": "The 74th Amendment Act, 1992 added Part IXA and the Twelfth Schedule on municipalities.", "qh": "किस संविधान संशोधन ने शहरी स्थानीय निकायों (नगरपालिकाओं) को संवैधानिक दर्जा दिया?", "oh": ["73वाँ संशोधन", "42वाँ संशोधन", "74वाँ संशोधन", "86वाँ संशोधन"], "eh": "74वें संशोधन अधिनियम, 1992 ने नगरपालिकाओं पर भाग IXA और बारहवीं अनुसूची जोड़ी।", "level": "tough"}, {"s": "General Awareness", "t": "Static GK", "q": "'Gitanjali' was written by:", "o": ["Bankim Chandra Chattopadhyay", "Rabindranath Tagore", "Sarojini Naidu", "Munshi Premchand"], "a": 1, "e": "Tagore's Gitanjali (English, 1912) won him the Nobel Prize in Literature in 1913.", "qh": "'गीतांजलि' किसने लिखी?", "oh": ["बंकिम चंद्र चट्टोपाध्याय", "रवींद्रनाथ टैगोर", "सरोजिनी नायडू", "मुंशी प्रेमचंद"], "eh": "टैगोर की गीतांजलि (अंग्रेज़ी, 1912) के लिए उन्हें 1913 में साहित्य का नोबेल मिला।", "level": "medium"}, {"s": "General Awareness", "t": "Polity", "q": "'Equality before law and equal protection of laws' is guaranteed by which Article?", "o": ["Article 19", "Article 21", "Article 15", "Article 14"], "a": 3, "e": "Article 14 guarantees equality before law and equal protection of the laws to all persons.", "qh": "'कानून के समक्ष समानता और कानूनों का समान संरक्षण' किस अनुच्छेद में दिया गया है?", "oh": ["अनुच्छेद 19", "अनुच्छेद 21", "अनुच्छेद 15", "अनुच्छेद 14"], "eh": "अनुच्छेद 14 सभी व्यक्तियों को कानून के समक्ष समानता और कानूनों का समान संरक्षण देता है।", "level": "easy"}, {"s": "General Awareness", "t": "Polity", "q": "President's Rule is imposed in a State under which Article?", "o": ["Article 352", "Article 360", "Article 370", "Article 356"], "a": 3, "e": "Article 356 deals with failure of constitutional machinery in a State. (352 – national emergency, 360 – financial emergency.)", "qh": "किसी राज्य में राष्ट्रपति शासन किस अनुच्छेद के तहत लगाया जाता है?", "oh": ["अनुच्छेद 352", "अनुच्छेद 360", "अनुच्छेद 370", "अनुच्छेद 356"], "eh": "अनुच्छेद 356 राज्य में संवैधानिक तंत्र विफल होने से जुड़ा है। (352 – राष्ट्रीय आपातकाल, 360 – वित्तीय आपातकाल।)", "level": "medium"}, {"s": "General Awareness", "t": "Economy", "q": "The National Pension System (NPS) is regulated by:", "o": ["IRDAI", "PFRDA", "SEBI", "NABARD"], "a": 1, "e": "The Pension Fund Regulatory and Development Authority (PFRDA) regulates NPS.", "qh": "राष्ट्रीय पेंशन प्रणाली (NPS) का नियामक कौन है?", "oh": ["IRDAI", "PFRDA", "SEBI", "NABARD"], "eh": "पेंशन निधि विनियामक और विकास प्राधिकरण (PFRDA) NPS को नियंत्रित करता है।", "level": "medium"}, {"s": "General Awareness", "t": "Economy", "q": "The share of deposits that banks must keep as cash with the RBI is called:", "o": ["Cash Reserve Ratio (CRR)", "Statutory Liquidity Ratio (SLR)", "Repo rate", "Bank rate"], "a": 0, "e": "CRR is held with the RBI as cash; SLR is kept by banks themselves in liquid assets such as government securities.", "qh": "बैंकों को अपनी जमा का जो हिस्सा RBI के पास नकद रखना होता है, उसे क्या कहते हैं?", "oh": ["नकद आरक्षित अनुपात (CRR)", "सांविधिक तरलता अनुपात (SLR)", "रेपो रेट", "बैंक दर"], "eh": "CRR नकद के रूप में RBI के पास रहता है; SLR बैंक खुद सरकारी प्रतिभूतियों जैसी तरल संपत्तियों में रखते हैं।", "level": "medium"}, {"s": "General Awareness", "t": "Current Affairs", "q": "The United Nations has declared 2026 as the International Year of:", "o": ["Millets", "Cooperatives", "the Woman Farmer", "Quantum Science and Technology"], "a": 2, "e": "2026 is the UN International Year of the Woman Farmer, led by FAO. (Millets – 2023; Cooperatives and Quantum Science – 2025.)", "qh": "संयुक्त राष्ट्र ने 2026 को किसका अंतरराष्ट्रीय वर्ष घोषित किया है?", "oh": ["मोटा अनाज (मिलेट्स)", "सहकारिता", "महिला किसान", "क्वांटम विज्ञान और प्रौद्योगिकी"], "eh": "2026 FAO के नेतृत्व में संयुक्त राष्ट्र का 'अंतरराष्ट्रीय महिला किसान वर्ष' है। (मिलेट्स – 2023; सहकारिता और क्वांटम विज्ञान – 2025।)", "level": "easy"}, {"s": "General Awareness", "t": "Art & Culture", "q": "Kalamkari, a hand-painted or block-printed cotton textile art, is mainly associated with:", "o": ["Bihar", "Rajasthan", "Andhra Pradesh", "Assam"], "a": 2, "e": "Kalamkari is made at Srikalahasti and Machilipatnam in Andhra Pradesh.", "qh": "हाथ से चित्रित या ब्लॉक-प्रिंट वाली सूती कपड़े की कला कलमकारी मुख्य रूप से किससे जुड़ी है?", "oh": ["बिहार", "राजस्थान", "आंध्र प्रदेश", "असम"], "eh": "कलमकारी आंध्र प्रदेश के श्रीकालहस्ती और मछलीपट्टनम में बनाई जाती है।", "level": "medium"}, {"s": "General Awareness", "t": "General Science", "q": "Absolute zero (0 K) on the Celsius scale is about:", "o": ["−273.15 °C", "−100 °C", "0 °C", "−173.15 °C"], "a": 0, "e": "0 K = −273.15 °C; T(K) = T(°C) + 273.15.", "qh": "परम शून्य (0 K) सेल्सियस पैमाने पर लगभग कितना है?", "oh": ["−273.15 °C", "−100 °C", "0 °C", "−173.15 °C"], "eh": "0 K = −273.15 °C; T(K) = T(°C) + 273.15।", "level": "medium"}, {"s": "General Awareness", "t": "Awards", "q": "The Templeton Prize 2026 was awarded to which Cambridge palaeontologist, known for his work on the Burgess Shale fossils and evolutionary convergence?", "o": ["Simon Conway Morris", "Richard Dawkins", "Francis Collins", "Frank Wilczek"], "a": 0, "e": "Professor Simon Conway Morris of the University of Cambridge received the 2026 Templeton Prize. (Francis Collins won in 2020 and Frank Wilczek in 2022.)", "qh": "2026 का टेम्पलटन पुरस्कार कैम्ब्रिज के किस जीवाश्म-विज्ञानी को मिला, जो बर्जेस शेल जीवाश्मों और विकासवादी अभिसरण पर काम के लिए जाने जाते हैं?", "oh": ["साइमन कॉनवे मॉरिस", "रिचर्ड डॉकिन्स", "फ़्रांसिस कॉलिन्स", "फ़्रैंक विल्ज़ेक"], "eh": "कैम्ब्रिज विश्वविद्यालय के प्रोफ़ेसर साइमन कॉनवे मॉरिस को 2026 का टेम्पलटन पुरस्कार मिला। (फ़्रांसिस कॉलिन्स को 2020 में और फ़्रैंक विल्ज़ेक को 2022 में मिला था।)", "level": "tough"}, {"s": "General Awareness", "t": "Geography", "q": "The Duncan Passage separates:", "o": ["Andaman and Nicobar groups", "South Andaman and Little Andaman", "Lakshadweep and Maldives", "India and Sri Lanka"], "a": 1, "e": "Duncan Passage lies between South Andaman and Little Andaman.", "qh": "डंकन पैसेज किन्हें अलग करता है?", "oh": ["अंडमान और निकोबार समूह", "दक्षिण अंडमान और लिटिल अंडमान", "लक्षद्वीप और मालदीव", "भारत और श्रीलंका"], "eh": "डंकन पैसेज दक्षिण अंडमान और लिटिल अंडमान के बीच है।", "level": "medium"}, {"s": "General Awareness", "t": "Railways", "q": "How many high-speed rail corridors, called 'growth connectors', were announced in the Union Budget 2026-27?", "o": ["Seven", "Five", "Nine", "Twelve"], "a": 0, "e": "The Finance Minister announced seven high-speed rail corridors (about 4,000 km, ₹16 lakh crore), including Mumbai–Pune, Hyderabad–Bengaluru, Chennai–Bengaluru, Delhi–Varanasi and Varanasi–Siliguri.", "qh": "केंद्रीय बजट 2026-27 में 'ग्रोथ कनेक्टर' कहे गए कितने हाई-स्पीड रेल कॉरिडोर घोषित किए गए?", "oh": ["सात", "पाँच", "नौ", "बारह"], "eh": "वित्त मंत्री ने सात हाई-स्पीड रेल कॉरिडोर (लगभग 4,000 km, ₹16 लाख करोड़) घोषित किए, जिनमें मुंबई–पुणे, हैदराबाद–बेंगलुरु, चेन्नई–बेंगलुरु, दिल्ली–वाराणसी और वाराणसी–सिलीगुड़ी शामिल हैं।", "level": "medium"}, {"s": "General Awareness", "t": "Economy", "q": "The 'Blue Revolution' in India is related to:", "o": ["Oilseed production", "Fish production", "Pulse production", "Wool production"], "a": 1, "e": "The Blue Revolution aims at growth of fisheries and aquaculture.", "qh": "भारत में 'नीली क्रांति' किससे जुड़ी है?", "oh": ["तिलहन उत्पादन", "मछली उत्पादन", "दलहन उत्पादन", "ऊन उत्पादन"], "eh": "नीली क्रांति का लक्ष्य मत्स्य पालन और जलीय कृषि को बढ़ाना है।", "level": "medium"}, {"s": "Mathematics", "t": "Speed, Time and Distance", "q": "A boat whose speed in still water is 8 km/h goes some distance downstream and comes back upstream in 6 hours in all. If the stream flows at 4 km/h, what is the one-way distance?", "o": ["18 km", "36 km", "23 km", "24 km"], "a": 0, "e": "D/12 + D/4 = 6 → D = 6 × 12 × 4/16 = 18 km.", "qh": "शांत पानी में 8 km/h की रफ़्तार वाली एक नाव धारा के साथ कुछ दूरी जाकर धारा के उलटे लौटती है, कुल 6 घंटे में। धारा की रफ़्तार 4 km/h हो, तो एक तरफ़ की दूरी कितनी है?", "oh": ["18 km", "36 km", "23 km", "24 km"], "eh": "D/12 + D/4 = 6 → D = 6 × 12 × 4/16 = 18 km।", "level": "medium"}, {"s": "Mathematics", "t": "Speed, Time and Distance", "q": "A boat whose speed in still water is 10 km/h goes some distance downstream and comes back upstream in 5 hours in all. If the stream flows at 2 km/h, what is the one-way distance?", "o": ["29 km", "30 km", "24 km", "48 km"], "a": 2, "e": "D/12 + D/8 = 5 → D = 5 × 12 × 8/20 = 24 km.", "qh": "शांत पानी में 10 km/h की रफ़्तार वाली एक नाव धारा के साथ कुछ दूरी जाकर धारा के उलटे लौटती है, कुल 5 घंटे में। धारा की रफ़्तार 2 km/h हो, तो एक तरफ़ की दूरी कितनी है?", "oh": ["29 km", "30 km", "24 km", "48 km"], "eh": "D/12 + D/8 = 5 → D = 5 × 12 × 8/20 = 24 km।", "level": "medium"}, {"s": "Mathematics", "t": "Simplification", "q": "Simplify: √400 − √25 × ∛27 = ?", "o": ["45", "8", "28", "5"], "a": 3, "e": "√400 = 20, √25 = 5, ∛27 = 3; 20 − 5 × 3 = 5.", "qh": "सरल कीजिए: √400 − √25 × ∛27 = ?", "oh": ["45", "8", "28", "5"], "eh": "√400 = 20, √25 = 5, ∛27 = 3; 20 − 5 × 3 = 5।", "level": "easy"}, {"s": "Mathematics", "t": "Time and Work", "q": "Arjun can finish a work in 30 days and Amit in 45 days. In how many days can they finish it working together?", "o": ["90 days", "37.5 days", "18 days", "17 days"], "a": 2, "e": "Work per day together = 1/30 + 1/45 = 1/18 → time = 18 days.", "qh": "अर्जुन एक काम 30 दिन में और अमित 45 दिन में पूरा कर सकता है। दोनों मिलकर वह काम कितने दिन में करेंगे?", "oh": ["90 दिन", "37.5 दिन", "18 दिन", "17 दिन"], "eh": "साथ में एक दिन का काम = 1/30 + 1/45 = 1/18 → समय = 18 दिन।", "level": "easy"}, {"s": "Mathematics", "t": "Percentage", "q": "The population of a town is 62,500. It increases by 4% in the first year and decreases by 10% in the second year. What is the population after 2 years?", "o": ["58,600", "58,300", "65,000", "58,500"], "a": 3, "e": "62,500 × 1.04 × 0.9 = 58,500.", "qh": "एक कस्बे की आबादी 62,500 है। यह पहले साल 4% बढ़ती है और दूसरे साल 10% घटती है। 2 साल बाद आबादी कितनी होगी?", "oh": ["58,600", "58,300", "65,000", "58,500"], "eh": "62,500 × 1.04 × 0.9 = 58,500।", "level": "tough"}, {"s": "Mathematics", "t": "Average and Statistics", "q": "The average of 9 consecutive numbers is 43. What is the largest of them?", "o": ["52", "47", "48", "39"], "a": 1, "e": "The average is the middle number 43; there are 4 numbers on each side with gap 1 → largest = 47.", "qh": "9 लगातार संख्याओं का औसत 43 है। उनमें सबसे बड़ी संख्या कौन-सी है?", "oh": ["52", "47", "48", "39"], "eh": "औसत ही बीच वाली संख्या 43 है; दोनों ओर 4 संख्याएँ, अंतर 1 → उत्तर = 47।", "level": "medium"}, {"s": "Mathematics", "t": "Mensuration", "q": "A rectangular field is 50 m long and 35 m wide. A path 2.5 m wide is built all around it on the outside. What is the area of the path?", "o": ["470 m²", "425 m²", "450 m²", "475 m²"], "a": 2, "e": "(50 + 5) × (35 + 5) − 50 × 35 = 450 m².", "qh": "एक आयताकार मैदान 50 m लंबा और 35 m चौड़ा है। उसके चारों ओर बाहर की तरफ़ 2.5 m चौड़ा रास्ता बना है। रास्ते का क्षेत्रफल कितना है?", "oh": ["470 m²", "425 m²", "450 m²", "475 m²"], "eh": "(50 + 5) × (35 + 5) − 50 × 35 = 450 m²।", "level": "easy"}, {"s": "Mathematics", "t": "Ratio and Proportion", "q": "Suresh starts a business with ₹40,000. After 6 months, Vikas joins with ₹50,000. At the end of the year the profit is ₹6,500. What is Vikas's share?", "o": ["₹2,500", "₹3,500", "₹3,250", "₹1,500"], "a": 0, "e": "Capital × months = 40000×12 : 50000×6 = 8 : 5. Share = 5/13 × ₹6,500 = ₹2,500.", "qh": "सुरेश ₹40,000 से कारोबार शुरू करता है। 6 महीने बाद विकास ₹50,000 लेकर जुड़ता है। साल के आखिर में लाभ ₹6,500 है। विकास का हिस्सा कितना है?", "oh": ["₹2,500", "₹3,500", "₹3,250", "₹1,500"], "eh": "पूँजी × महीने = 40000×12 : 50000×6 = 8 : 5। हिस्सा = 5/13 × ₹6,500 = ₹2,500।", "level": "easy"}, {"s": "Mathematics", "t": "Algebra", "q": "The sum of the digits of a two-digit number is 17. When the digits are reversed, the new number is 9 more than the original number. What is the original number?", "o": ["98", "90", "89", "88"], "a": 2, "e": "9(u − t) = 9 → u − t = 1; u + t = 17 → u = 9, t = 8; number = 89.", "qh": "दो अंकों की एक संख्या के अंकों का योग 17 है। अंकों को उलटने पर नई संख्या मूल संख्या से 9 अधिक हो जाती है। मूल संख्या क्या है?", "oh": ["98", "90", "89", "88"], "eh": "9(u − t) = 9 → u − t = 1; u + t = 17 → u = 9, t = 8; संख्या = 89।", "level": "tough"}, {"s": "Mathematics", "t": "Mensuration", "q": "What is the total surface area of a solid hemisphere with radius 21 cm? (Take π = 22/7)", "o": ["4158 cm²", "2079 cm²", "8316 cm²", "4180 cm²"], "a": 0, "e": "3πr² = 3 × 22/7 × 21² = 4158 cm².", "qh": "21 cm त्रिज्या वाले ठोस अर्धगोले का कुल पृष्ठीय क्षेत्रफल कितना है? (π = 22/7 लें)", "oh": ["4158 cm²", "2079 cm²", "8316 cm²", "4180 cm²"], "eh": "3πr² = 3 × 22/7 × 21² = 4158 cm²।", "level": "tough"}, {"s": "Mathematics", "t": "Time and Work", "q": "16 workers can build a wall in 10 days. How many days will 10 workers take to build the same wall?", "o": ["15 days", "18 days", "7.25 days", "16 days"], "a": 3, "e": "Work = 16 × 10 = 160 worker-days. Days = 160/10 = 16.", "qh": "16 मज़दूर एक दीवार 10 दिन में बना सकते हैं। 10 मज़दूर वही दीवार कितने दिन में बनाएँगे?", "oh": ["15 दिन", "18 दिन", "7.25 दिन", "16 दिन"], "eh": "काम = 16 × 10 = 160 मज़दूर-दिन। दिन = 160/10 = 16।", "level": "easy"}, {"s": "Mathematics", "t": "Number System", "q": "The HCF of two numbers is 15 and their LCM is 270. If one of the numbers is 30, what is the other number?", "o": ["135", "120", "150", "18"], "a": 0, "e": "Product of numbers = HCF × LCM → other = 15 × 270/30 = 135.", "qh": "दो संख्याओं का HCF 15 और LCM 270 है। अगर एक संख्या 30 है, तो दूसरी संख्या क्या है?", "oh": ["135", "120", "150", "18"], "eh": "संख्याओं का गुणनफल = HCF × LCM → दूसरी = 15 × 270/30 = 135।", "level": "medium"}, {"s": "Mathematics", "t": "Average and Statistics", "q": "The average of 5 consecutive even numbers is 20. What is the largest of them?", "o": ["25", "24", "26", "22"], "a": 1, "e": "The average is the middle number 20; there are 2 numbers on each side with gap 2 → largest = 24.", "qh": "5 लगातार सम संख्याओं का औसत 20 है। उनमें सबसे बड़ी संख्या कौन-सी है?", "oh": ["25", "24", "26", "22"], "eh": "औसत ही बीच वाली संख्या 20 है; दोनों ओर 2 संख्याएँ, अंतर 2 → उत्तर = 24।", "level": "tough"}, {"s": "Mathematics", "t": "Percentage", "q": "The population of a town is 25,000. It increases by 10% every year. What will the population be after 2 years?", "o": ["27,500", "30,000", "30,050", "30,250"], "a": 3, "e": "25,000 × 1.1 × 1.1 = 30,250.", "qh": "एक कस्बे की आबादी 25,000 है। यह हर साल 10% बढ़ती है। 2 साल बाद आबादी कितनी होगी?", "oh": ["27,500", "30,000", "30,050", "30,250"], "eh": "25,000 × 1.1 × 1.1 = 30,250।", "level": "medium"}, {"s": "Mathematics", "t": "Geometry", "q": "A ladder reaches a window 12 m above the ground. If the ladder is 13 m long, how far is its foot from the base of the wall?", "o": ["5 m", "6 m", "1 m", "7 m"], "a": 0, "e": "Distance = √(13² − 12²) = √25 = 5 m.", "qh": "एक सीढ़ी ज़मीन से 12 m ऊँची खिड़की तक पहुँचती है। अगर सीढ़ी 13 m लंबी है, तो उसका निचला सिरा दीवार के आधार से कितनी दूर है?", "oh": ["5 m", "6 m", "1 m", "7 m"], "eh": "दूरी = √(13² − 12²) = √25 = 5 m।", "level": "easy"}, {"s": "Mathematics", "t": "Profit and Loss", "q": "Suresh bought an old scooter for ₹17,500 and spent ₹1,800 on repairs. He sold it for ₹20,265. What is his profit percentage?", "o": ["10%", "7.5%", "15.8%", "5%"], "a": 3, "e": "Total CP = ₹17,500 + ₹1,800 = ₹19,300; profit = ₹965; profit % = ₹965/₹19,300 × 100 = 5%.", "qh": "सुरेश ने एक पुराना स्कूटर ₹17,500 में खरीदा और ₹1,800 मरम्मत पर खर्च किए। उसने इसे ₹20,265 में बेचा। उसका लाभ प्रतिशत क्या है?", "oh": ["10%", "7.5%", "15.8%", "5%"], "eh": "कुल क्रय मूल्य = ₹17,500 + ₹1,800 = ₹19,300; लाभ = ₹965; लाभ % = ₹965/₹19,300 × 100 = 5%।", "level": "easy"}, {"s": "Mathematics", "t": "Interest", "q": "A sum of money at simple interest amounts to ₹5,500 in 2 years and to ₹6,000 in 4 years. What is the rate of interest per annum?", "o": ["3%", "6%", "5%", "50/11%"], "a": 2, "e": "Interest for 2 years = ₹500 → ₹250 per year. Principal = ₹5,500 − 2 × ₹250 = ₹5,000. Rate = ₹250/₹5,000 × 100 = 5%.", "qh": "साधारण ब्याज पर कोई रकम 2 साल में ₹5,500 और 4 साल में ₹6,000 हो जाती है। वार्षिक ब्याज दर क्या है?", "oh": ["3%", "6%", "5%", "50/11%"], "eh": "2 साल का ब्याज = ₹500 → हर साल ₹250। मूलधन = ₹5,500 − 2 × ₹250 = ₹5,000। दर = ₹250/₹5,000 × 100 = 5%।", "level": "tough"}, {"s": "Mathematics", "t": "Profit and Loss", "q": "By selling 30 metres of cloth, a trader loses an amount equal to the selling price of 2 metres of cloth. What is his loss percentage?", "o": ["11.25%", "7 1/7%", "6.25%", "6 2/3%"], "a": 2, "e": "Loss = SP of 2, so CP of 30 = SP of 32. Loss % = 2/32 × 100 = 6.25%.", "qh": "30 मीटर कपड़ा बेचकर एक व्यापारी को 2 मीटर कपड़ा के विक्रय मूल्य के बराबर हानि होती है। उसका हानि प्रतिशत क्या है?", "oh": ["11.25%", "7 1/7%", "6.25%", "6 2/3%"], "eh": "हानि = 2 का विक्रय मूल्य, इसलिए 30 का क्रय मूल्य = 32 का विक्रय मूल्य। हानि % = 2/32 × 100 = 6.25%।", "level": "easy"}, {"s": "Mathematics", "t": "Number System", "q": "What is the remainder when 448 + 928 + 396 is divided by 11?", "o": ["3", "1", "0", "4"], "a": 1, "e": "Remainders: 8 + 4 + 0 = 12; 12 mod 11 = 1.", "qh": "448 + 928 + 396 को 11 से भाग देने पर शेषफल क्या होगा?", "oh": ["3", "1", "0", "4"], "eh": "शेषफल: 8 + 4 + 0 = 12; इसे 11 से भाग देने पर शेष 1।", "level": "medium"}, {"s": "Mathematics", "t": "Ratio and Proportion", "q": "What is the third proportional to 12 and 24?", "o": ["72", "48", "45", "50"], "a": 1, "e": "12 : 24 = 24 : x → x = 24²/12 = 576/12 = 48.", "qh": "12 और 24 का तीसरा समानुपाती क्या है?", "oh": ["72", "48", "45", "50"], "eh": "12 : 24 = 24 : x → x = 24²/12 = 576/12 = 48।", "level": "tough"}, {"s": "Mathematics", "t": "Number System", "q": "What is the unit digit of 2^66?", "o": ["5", "7", "4", "9"], "a": 2, "e": "Unit digits of powers of 2 repeat as 2, 4, 8, 6 (cycle 4). 66 mod 4 = 2 → unit digit 4.", "qh": "2^66 का इकाई अंक क्या है?", "oh": ["5", "7", "4", "9"], "eh": "2 की घातों के इकाई अंक 2, 4, 8, 6 दोहराते हैं (चक्र 4)। 66 को 4 से भाग देने पर 2 → इकाई अंक 4।", "level": "easy"}, {"s": "Mathematics", "t": "Trigonometry", "q": "If tan θ = 5/12, what is sin θ? (θ is acute)", "o": ["13/5", "12/13", "13/12", "5/13"], "a": 3, "e": "Opposite = 5, adjacent = 12, hypotenuse = √(5² + 12²) = 13. sin θ = 5/13.", "qh": "अगर tan θ = 5/12 है, तो sin θ क्या है? (θ न्यून कोण है)", "oh": ["13/5", "12/13", "13/12", "5/13"], "eh": "सामने की भुजा = 5, आसन्न भुजा = 12, कर्ण = √(5² + 12²) = 13. sin θ = 5/13।", "level": "easy"}, {"s": "Mathematics", "t": "Interest", "q": "A sum lent at simple interest becomes three times the principal after 8 years. Find the annual rate of interest.", "o": ["37.5%", "25%", "4 1/6%", "27%"], "a": 1, "e": "Interest = 2 × P = P × R × 8/100 → R = 200/8 = 25%.", "qh": "साधारण ब्याज पर दी गई एक राशि 8 साल बाद मूलधन की तीन गुनी हो जाती है। वार्षिक ब्याज दर बताइए।", "oh": ["37.5%", "25%", "4 1/6%", "27%"], "eh": "ब्याज = 2 × P = P × R × 8/100 → R = 200/8 = 25%।", "level": "medium"}, {"s": "Mathematics", "t": "Ages", "q": "The present ages of Neha and Geeta are in the ratio 2 : 3. After 4 years, the ratio will be 5 : 7. What is Geeta's present age?", "o": ["28 years", "36 years", "24 years", "20 years"], "a": 2, "e": "(2x + 4)/(3x + 4) = 5/7 → x = 8; age = 3 × 8 = 24 years.", "qh": "नेहा और गीता की अभी की आयु का अनुपात 2 : 3 है। 4 साल बाद यह अनुपात 5 : 7 हो जाएगा। गीता की अभी की आयु कितनी है?", "oh": ["28 साल", "36 साल", "24 साल", "20 साल"], "eh": "(2x + 4)/(3x + 4) = 5/7 → x = 8; आयु = 3 × 8 = 24 साल।", "level": "medium"}, {"s": "Mathematics", "t": "Number System", "q": "The HCF of two numbers is 8 and their LCM is 144. If one of the numbers is 16, what is the other number?", "o": ["80", "64", "72", "24"], "a": 2, "e": "Product of numbers = HCF × LCM → other = 8 × 144/16 = 72.", "qh": "दो संख्याओं का HCF 8 और LCM 144 है। अगर एक संख्या 16 है, तो दूसरी संख्या क्या है?", "oh": ["80", "64", "72", "24"], "eh": "संख्याओं का गुणनफल = HCF × LCM → दूसरी = 8 × 144/16 = 72।", "level": "medium"}, {"s": "Mathematics", "t": "Ratio and Proportion", "q": "The incomes of Rohit and Amit are in the ratio 7 : 5 and their expenditures are in the ratio 5 : 3. If each of them saves ₹1,000, what is Rohit's income?", "o": ["₹3,500", "₹4,500", "₹2,500", "₹3,501"], "a": 0, "e": "7x − 5y = 5x − 3y = 1000 → 2x = 2y. Solving: x = 500, y = 500, so income = 7 × 500 = ₹3,500.", "qh": "रोहित और अमित की आय का अनुपात 7 : 5 और खर्च का अनुपात 5 : 3 है। अगर दोनों ₹1,000 बचाते हैं, तो रोहित की आय कितनी है?", "oh": ["₹3,500", "₹4,500", "₹2,500", "₹3,501"], "eh": "7x − 5y = 5x − 3y = 1000 → 2x = 2y। हल करने पर x = 500, y = 500, आय = 7 × 500 = ₹3,500।", "level": "medium"}, {"s": "Mathematics", "t": "Algebra", "q": "The cost of 4 pens and 4 notebooks is ₹196, and the cost of 4 pens and 5 notebooks is ₹224. What is the cost of one notebook?", "o": ["₹30", "₹25", "₹28", "₹49"], "a": 2, "e": "4p + 4n = 196, 4p + 5n = 224. Eliminating p: n = (4×224 − 4×196)/(4×5 − 4×4) = ₹28; pen = ₹21.", "qh": "4 पेन और 4 कॉपियों का दाम ₹196 है, और 4 पेन और 5 कॉपियों का दाम ₹224 है। एक कॉपी का दाम कितना है?", "oh": ["₹30", "₹25", "₹28", "₹49"], "eh": "4p + 4n = 196, 4p + 5n = 224। p हटाने पर: n = (4×224 − 4×196)/(4×5 − 4×4) = ₹28; पेन = ₹21।", "level": "medium"}, {"s": "Mathematics", "t": "Profit and Loss", "q": "Successive discounts of 25% and 40% are equivalent to a single discount of:", "o": ["64%", "56%", "53%", "55%"], "a": 3, "e": "Price left = 0.75 × 0.6 = 0.45. Single discount = 55%.", "qh": "25% और 40% की लगातार छूट किस एक छूट के बराबर हैं?", "oh": ["64%", "56%", "53%", "55%"], "eh": "बचा दाम = 0.75 × 0.6 = 0.45। एक छूट = 55%।", "level": "medium"}, {"s": "Mathematics", "t": "Simplification", "q": "Simplify: 60% of 580 − 20% of 540 = ?", "o": ["240", "456", "235", "242"], "a": 0, "e": "60% of 580 = 348; 20% of 540 = 108; result = 240.", "qh": "सरल कीजिए: 580 का 60% − 540 का 20% = ?", "oh": ["240", "456", "235", "242"], "eh": "580 का 60% = 348; 540 का 20% = 108; परिणाम = 240।", "level": "easy"}, {"s": "Mathematics", "t": "Profit and Loss", "q": "The cost price of a water purifier is ₹720. At what price must it be marked so that after allowing a 10% discount, the seller gains 35%?", "o": ["₹1,044", "₹1,140", "₹1,080", "₹1,040"], "a": 2, "e": "SP = ₹720 × 135/100 = ₹972; MP = SP × 100/90 = ₹1,080.", "qh": "एक वॉटर प्यूरीफ़ायर का क्रय मूल्य ₹720 है। इस पर कितना अंकित मूल्य लिखा जाए कि 10% छूट देने के बाद भी विक्रेता को 35% लाभ हो?", "oh": ["₹1,044", "₹1,140", "₹1,080", "₹1,040"], "eh": "विक्रय मूल्य = ₹720 × 135/100 = ₹972; अंकित मूल्य = विक्रय मूल्य × 100/90 = ₹1,080।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Coding-Decoding", "q": "In a certain code language, 'FRUIT' is coded as 61. How will 'PAINT' be coded in that language?", "o": ["73", "76", "75", "60"], "a": 2, "e": "Code = sum of reverse positions (A = 26, B = 25, …). For PAINT: 75.", "qh": "एक कोड भाषा में 'FRUIT' को 61 लिखा जाता है। उसी भाषा में 'PAINT' को कैसे लिखा जाएगा?", "oh": ["73", "76", "75", "60"], "eh": "कोड = उलटी स्थितियों का योग (A = 26, B = 25, …)। PAINT के लिए: 75।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Mathematical Operations", "q": "If '+' means '−', '−' means '÷', '×' means '+', '÷' means '×', then what is the value of the following expression?\n17 ÷ 15 × 24 + 19 × 8 = ?", "o": ["278", "268", "265", "536"], "a": 1, "e": "Replace the signs: 17 × 15 + 24 − 19 + 8 = 268 (using BODMAS).", "qh": "अगर '+' का मतलब '−', '−' का मतलब '÷', '×' का मतलब '+', '÷' का मतलब '×' हो, तो नीचे दिए व्यंजक का मान क्या होगा?\n17 ÷ 15 × 24 + 19 × 8 = ?", "oh": ["278", "268", "265", "536"], "eh": "चिह्न बदलें: 17 × 15 + 24 − 19 + 8 = 268 (BODMAS से)।", "level": "tough"}, {"s": "General Intelligence and Reasoning", "t": "Odd One Out", "q": "Three of the following four options are alike in a certain way and one is different. Select the odd one.", "o": ["Cheetah", "Tiger", "Wolf", "Leopard"], "a": 2, "e": "Wolf belongs to the dog family; the others are big cats.", "qh": "नीचे दिए गए चार विकल्पों में से तीन किसी तरह एक जैसे हैं और एक अलग है। अलग वाला चुनिए।", "oh": ["चीता", "बाघ", "भेड़िया", "तेंदुआ"], "eh": "भेड़िया कुत्ते के परिवार का है; बाकी बिल्ली परिवार के हैं।", "level": "tough"}, {"s": "General Intelligence and Reasoning", "t": "Directions", "q": "Ajay is facing East. Ajay turns 180° clockwise, then 90° clockwise. Which direction is Ajay facing now?", "o": ["East", "West", "South", "North"], "a": 3, "e": "Net turn = 270° (clockwise 270°). From East this gives North.", "qh": "अजय का मुँह पूर्व की ओर है। अजय 180° दक्षिणावर्त, फिर 90° दक्षिणावर्त घूमता/घूमती है। अब उसका मुँह किस दिशा में है?", "oh": ["पूर्व", "पश्चिम", "दक्षिण", "उत्तर"], "eh": "कुल घुमाव = 270°। पूर्व से यह उत्तर देता है।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Ranking", "q": "In a row of 42 people, Amit is 6th from the left and Naveen is 5th from the right. How many people are there between them?", "o": ["29", "30", "31", "32"], "a": 2, "e": "Naveen is 38th from the left. Between = 38 − 6 − 1 = 31.", "qh": "42 लोगों की पंक्ति में अमित बाएँ से 6वें और नवीन दाएँ से 5वें स्थान पर है। दोनों के बीच कितने लोग हैं?", "oh": ["29", "30", "31", "32"], "eh": "नवीन बाएँ से 38वें स्थान पर है। बीच में = 38 − 6 − 1 = 31।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Clock (Mirror Image)", "q": "A clock shows the time 7:40. What time will its mirror image show?", "o": ["5:20", "3:20", "4:30", "4:20"], "a": 3, "e": "Mirror time = 11:60 − 7:40 = 4:20.", "qh": "एक घड़ी 7:40 का समय दिखा रही है। दर्पण में उसका प्रतिबिंब कौन-सा समय दिखाएगा?", "oh": ["5:20", "3:20", "4:30", "4:20"], "eh": "दर्पण का समय = 11:60 − 7:40 = 4:20।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Coding-Decoding", "q": "In a certain code language, 'PLANET' is written as 'LPANWH'. How will 'CASTLE' be written in that language?", "o": ["WPHIAY", "YAIHPW", "AYQRJC", "AYIHPW"], "a": 1, "e": "Rule: each letter is replaced by its opposite letter and then moved +1. Applying it to CASTLE gives YAIHPW.", "qh": "एक कोड भाषा में 'PLANET' को 'LPANWH' लिखा जाता है। उसी भाषा में 'CASTLE' को कैसे लिखा जाएगा?", "oh": ["WPHIAY", "YAIHPW", "AYQRJC", "AYIHPW"], "eh": "नियम: हर अक्षर उलटे अक्षर से बदलकर फिर +1 खिसकता है। CASTLE पर लगाने से YAIHPW मिलता है।", "level": "tough"}, {"s": "General Intelligence and Reasoning", "t": "Blood Relations", "q": "M is the brother of R. R is the daughter of B. B is the husband of P. P is the daughter of Q. How is M related to Q?", "o": ["Grandson", "Grandfather", "Father-in-law", "Uncle"], "a": 0, "e": "Draw the family tree: M → R: brother; R → B: daughter; B → P: husband; P → Q: daughter. So M is the grandson of Q.", "qh": "M, R का भाई है। R, B की बेटी है। B, P का पति है। P, Q की बेटी है। M का Q से क्या संबंध है?", "oh": ["पोता/नाती", "दादा/नाना", "ससुर", "चाचा/मामा"], "eh": "परिवार का चार्ट बनाएँ: M → R: भाई; R → B: बेटी; B → P: पति; P → Q: बेटी। इसलिए M, Q का पोता/नाती है।", "level": "tough"}, {"s": "General Intelligence and Reasoning", "t": "Analogy", "q": "Select the option that is related to the third term in the same way as the second term is related to the first term.\nCow : Calf :: Horse : ?", "o": ["Foal", "Pony", "Mare", "Stable"], "a": 0, "e": "Relation: 'young one'. Cow – Calf, so Horse – Foal.", "qh": "वह विकल्प चुनिए जो तीसरे पद से उसी तरह जुड़ा है, जैसे दूसरा पद पहले पद से जुड़ा है।\nगाय : बछड़ा :: घोड़ा : ?", "oh": ["घोड़े का बच्चा (फ़ोल)", "टट्टू", "घोड़ी", "अस्तबल"], "eh": "संबंध: 'बच्चा'। गाय – बछड़ा, इसलिए घोड़ा – घोड़े का बच्चा (फ़ोल)।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Analogy", "q": "Select the option that is related to the third term in the same way as the second term is related to the first term.\n7 : 49 :: 4 : ?", "o": ["24", "17", "12", "16"], "a": 3, "e": "Rule: x → x². 7 → 49, so 4 → 16.", "qh": "वह विकल्प चुनिए जो तीसरे पद से उसी तरह जुड़ा है, जैसे दूसरा पद पहले पद से जुड़ा है।\n7 : 49 :: 4 : ?", "oh": ["24", "17", "12", "16"], "eh": "नियम: x → x²। 7 → 49, इसलिए 4 → 16।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Syllogism", "q": "Read the given statements and conclusions carefully. Assuming that the information given in the statements is true, even if it appears to be at variance with commonly known facts, decide which of the given conclusions logically follow(s) from the statements.\nStatements:\nNo keys are tables.\nSome tables are not lamps.\nSome lamps are not doors.\nConclusions:\nI. All keys are tables.\nII. Some tables are keys.", "o": ["Only conclusion I follows", "Neither I nor II follows", "Only conclusion II follows", "Both I and II follow"], "a": 1, "e": "Each conclusion fails in at least one possible diagram, and they do not form an either–or pair.", "qh": "दिए गए कथनों और निष्कर्षों को ध्यान से पढ़िए। कथनों को सही मानते हुए, भले ही वे आम जानकारी से अलग लगें, तय कीजिए कि कौन-सा/से निष्कर्ष कथनों से तर्क के आधार पर निकलता/निकलते है/हैं।\nकथन:\nकोई भी चाबियाँ मेज़ें नहीं है।\nकुछ मेज़ें लैंप नहीं हैं।\nकुछ लैंप दरवाज़े नहीं हैं।\nनिष्कर्ष:\nI. सभी चाबियाँ मेज़ें हैं।\nII. कुछ मेज़ें चाबियाँ हैं।", "oh": ["केवल निष्कर्ष I सही है", "न I सही है, न II", "केवल निष्कर्ष II सही है", "I और II दोनों सही हैं"], "eh": "हर निष्कर्ष किसी न किसी आरेख में गलत हो जाता है, और ये 'या तो–या' वाली जोड़ी नहीं हैं।", "level": "tough"}, {"s": "General Intelligence and Reasoning", "t": "Series", "q": "What should come in place of the question mark (?) in the given series?\nA81Z, C100Y, E121X, G144W, ?", "o": ["I168V", "H169U", "J169V", "I169V"], "a": 3, "e": "First letter +2; number: consecutive squares; last letter -1. So ? = I169V.", "qh": "दी गई शृंखला में प्रश्न-चिह्न (?) की जगह क्या आएगा?\nA81Z, C100Y, E121X, G144W, ?", "oh": ["I168V", "H169U", "J169V", "I169V"], "eh": "पहला अक्षर +2; संख्या: लगातार वर्ग संख्याएँ; आखिरी अक्षर -1। इसलिए ? = I169V।", "level": "tough"}, {"s": "General Intelligence and Reasoning", "t": "Analogy", "q": "Select the option that is related to the third term in the same way as the second term is related to the first term.\nDRZ : FTX :: MCF : ?", "o": ["DEO", "KAH", "OED", "OEE"], "a": 2, "e": "Each letter moves +2, +2, -2 in order. MCF → OED.", "qh": "वह विकल्प चुनिए जो तीसरे पद से उसी तरह जुड़ा है, जैसे दूसरा पद पहले पद से जुड़ा है।\nDRZ : FTX :: MCF : ?", "oh": ["DEO", "KAH", "OED", "OEE"], "eh": "हर अक्षर क्रम से +2, +2, -2 खिसकता है। MCF → OED।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Series", "q": "What should come in place of the question mark (?) in the given series?\nB2Z, F4Y, J8X, N16W, ?", "o": ["Q32U", "R32V", "R32W", "R31V"], "a": 1, "e": "First letter +4; number: double each time; last letter -1. So ? = R32V.", "qh": "दी गई शृंखला में प्रश्न-चिह्न (?) की जगह क्या आएगा?\nB2Z, F4Y, J8X, N16W, ?", "oh": ["Q32U", "R32V", "R32W", "R31V"], "eh": "पहला अक्षर +4; संख्या: हर बार दोगुना; आखिरी अक्षर -1। इसलिए ? = R32V।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Venn Diagram", "q": "In a group of 80 people, 40 like Hindi, 28 like English and 14 like both. How many like neither?", "o": ["23", "26", "54", "31"], "a": 1, "e": "At least one = 40 + 28 − 14 = 54; neither = 80 − 54 = 26.", "qh": "80 लोगों के समूह में 40 को हिंदी पसंद है, 28 को अंग्रेज़ी पसंद है और 14 को दोनों पसंद हैं। कितने लोगों को दोनों में से कुछ भी पसंद नहीं है?", "oh": ["23", "26", "54", "31"], "eh": "कम से कम एक = 40 + 28 − 14 = 54; कोई नहीं = 80 − 54 = 26।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Directions", "q": "Rohit starts from point P, walks 3 km towards North, then turns left and walks 4 km, then turns left and walks 2 km. In which direction is Rohit now with respect to point P?", "o": ["North-West", "South-East", "East", "South"], "a": 0, "e": "Net East–West = -4 km, net North–South = +1 km; direction = North-West.", "qh": "रोहित बिंदु P से शुरू करके उत्तर की ओर 3 km चलता है, फिर बाएँ मुड़कर 4 km चलता है, फिर बाएँ मुड़कर 2 km चलता है। अब रोहित बिंदु P से किस दिशा में है?", "oh": ["उत्तर-पश्चिम", "दक्षिण-पूर्व", "पूर्व", "दक्षिण"], "eh": "कुल पूर्व–पश्चिम = -4 km, कुल उत्तर–दक्षिण = +1 km; दिशा = उत्तर-पश्चिम।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Symbol Series", "q": "How many pairs of letters are there in the word 'BRIGHTEN' which have as many letters between them in the word as there are between them in the English alphabet (in either direction)?", "o": ["3", "2", "4", "5"], "a": 0, "e": "Pairs: IE, IN, GH → 3.", "qh": "शब्द 'BRIGHTEN' में अक्षरों के ऐसे कितने जोड़े हैं जिनके बीच शब्द में उतने ही अक्षर हैं जितने अंग्रेज़ी वर्णमाला में उनके बीच हैं (किसी भी दिशा में)?", "oh": ["3", "2", "4", "5"], "eh": "जोड़े: IE, IN, GH → 3।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Odd One Out", "q": "Three of the following four options are alike in a certain way and one is different. Select the odd one.", "o": ["9 – 81", "10 – 100", "7 – 49", "12 – 146"], "a": 3, "e": "In all except 12 – 146: second number is the square of the first.", "qh": "नीचे दिए गए चार विकल्पों में से तीन किसी तरह एक जैसे हैं और एक अलग है। अलग वाला चुनिए।", "oh": ["9 – 81", "10 – 100", "7 – 49", "12 – 146"], "eh": "12 – 146 को छोड़कर सभी में: दूसरी संख्या पहली का वर्ग है।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Series", "q": "What should come in place of the question mark (?) in the given series?\n32, 47, 62, 77, 92, 107, ?", "o": ["122", "121", "118", "214"], "a": 0, "e": "Rule: Add 15 each time. So ? = 122.", "qh": "दी गई शृंखला में प्रश्न-चिह्न (?) की जगह क्या आएगा?\n32, 47, 62, 77, 92, 107, ?", "oh": ["122", "121", "118", "214"], "eh": "नियम: हर बार 15 जोड़ें। इसलिए ? = 122।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Seating Arrangement", "q": "K, D, U, L and J are sitting in a row, all facing North.\nJ sits second to the right of L.\nExactly 2 persons sit between D and J.\nL sits second to the right of U.\nD does not sit at either end.\nWho sits immediately to the right of K?", "o": ["L", "K", "J", "U"], "a": 2, "e": "Only one order fits all clues (left to right): U D L K J. Answer: J.", "qh": "K, D, U, L और J एक पंक्ति में उत्तर की ओर मुँह करके बैठे हैं।\nJ, L के दाईं ओर दूसरे स्थान पर बैठा है।\nD और J के बीच ठीक 2 व्यक्ति बैठे हैं।\nL, U के दाईं ओर दूसरे स्थान पर बैठा है।\nD किसी भी छोर पर नहीं बैठा है।\nK के ठीक दाईं ओर कौन बैठा है?", "oh": ["L", "K", "J", "U"], "eh": "सभी शर्तों पर केवल एक क्रम बैठता है (बाएँ से दाएँ): U D L K J। उत्तर: J।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Mathematical Operations", "q": "If '+' means '÷', '−' means '×', '×' means '−', '÷' means '+', then what is the value of the following expression?\n22 ÷ 16 ÷ 4 ÷ 9 − 21 = ?", "o": ["233", "231", "228", "462"], "a": 1, "e": "Replace the signs: 22 + 16 + 4 + 9 × 21 = 231 (using BODMAS).", "qh": "अगर '+' का मतलब '÷', '−' का मतलब '×', '×' का मतलब '−', '÷' का मतलब '+' हो, तो नीचे दिए व्यंजक का मान क्या होगा?\n22 ÷ 16 ÷ 4 ÷ 9 − 21 = ?", "oh": ["233", "231", "228", "462"], "eh": "चिह्न बदलें: 22 + 16 + 4 + 9 × 21 = 231 (BODMAS से)।", "level": "tough"}, {"s": "General Intelligence and Reasoning", "t": "Puzzle", "q": "5 boxes S, W, V, Q and U are kept one above the other (not necessarily in this order).\nBox W is neither at the top nor at the bottom.\nBox W is 2nd from the bottom.\nExactly 2 boxes are placed between boxes S and W.\nBox U is placed somewhere above box V.\nExactly 2 boxes are placed between boxes V and U.\nWhich box is at the top?", "o": ["S", "U", "W", "Q"], "a": 0, "e": "Only one order fits (bottom to top): V W Q U S. Answer: S.", "qh": "5 डिब्बे S, W, V, Q और U एक के ऊपर एक रखे हैं (ज़रूरी नहीं कि इसी क्रम में)।\nडिब्बा W न सबसे ऊपर है, न सबसे नीचे।\nडिब्बा W नीचे से 2वें स्थान पर है।\nडिब्बे S और W के बीच ठीक 2 डिब्बे रखे हैं।\nडिब्बा U, डिब्बे V से कहीं ऊपर रखा है।\nडिब्बे V और U के बीच ठीक 2 डिब्बे रखे हैं।\nसबसे ऊपर कौन-सा डिब्बा है?", "oh": ["S", "U", "W", "Q"], "eh": "केवल एक क्रम बैठता है (नीचे से ऊपर): V W Q U S। उत्तर: S।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Digit Operations", "q": "The following questions are based on the five three-digit numbers given below.\n158   827   516   349   763\nFor the number whose digits add up to the smallest total, what is the product of its first and last digits?", "o": ["30", "29", "31", "33"], "a": 0, "e": "Digit sums: 14, 17, 12, 16, 16. Smallest belongs to 516: 5 × 6 = 30.", "qh": "नीचे दी गई पाँच तीन-अंकीय संख्याओं के आधार पर प्रश्न का उत्तर दीजिए।\n158   827   516   349   763\nजिस संख्या के अंकों का योग सबसे कम है, उसके पहले और आखिरी अंक का गुणनफल क्या है?", "oh": ["30", "29", "31", "33"], "eh": "अंकों के योग: 14, 17, 12, 16, 16। सबसे कम 516 का है: 5 × 6 = 30।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Blood Relations", "q": "'A + B' means 'A is the husband of B'; 'A # B' means 'A is the father of B'; 'A × B' means 'A is the sister of B'; 'A $ B' means 'A is the daughter of B'. If C # A $ N, how is C related to N?", "o": ["Brother-in-law", "Husband", "Son", "Son-in-law"], "a": 1, "e": "Decode: C is the father of A; A is the daughter of N. So C is the husband of N.", "qh": "'A + B' का अर्थ है 'A, B का पति है'; 'A # B' का अर्थ है 'A, B का पिता है'; 'A × B' का अर्थ है 'A, B की बहन है'; 'A $ B' का अर्थ है 'A, B की बेटी है'। अगर C # A $ N, तो C का N से क्या संबंध है?", "oh": ["साला/देवर/जीजा", "पति", "बेटा", "दामाद"], "eh": "अर्थ निकालें: C, A का पिता; A, N की बेटी। इसलिए C, N का पति है।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Series", "q": "What should come in place of the question mark (?) in the given series?\nRIX, SKZ, TMB, UOD, ?", "o": ["VQG", "VRF", "WQF", "VQF"], "a": 3, "e": "Letter positions move by +1, +2, +2 (for 1st, 2nd, 3rd letters). So ? = VQF.", "qh": "दी गई शृंखला में प्रश्न-चिह्न (?) की जगह क्या आएगा?\nRIX, SKZ, TMB, UOD, ?", "oh": ["VQG", "VRF", "WQF", "VQF"], "eh": "अक्षरों की स्थिति +1, +2, +2 से बदलती है (पहले, दूसरे, तीसरे अक्षर के लिए)। इसलिए ? = VQF।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Odd One Out", "q": "Three of the following four options are alike in a certain way and one is different. Select the odd one.", "o": ["GHKN", "LMPS", "FGIL", "JKNQ"], "a": 2, "e": "In GHKN, LMPS, JKNQ the gaps are +1, +3, +3; in FGIL they are +1, +2, +3.", "qh": "नीचे दिए गए चार विकल्पों में से तीन किसी तरह एक जैसे हैं और एक अलग है। अलग वाला चुनिए।", "oh": ["GHKN", "LMPS", "FGIL", "JKNQ"], "eh": "GHKN, LMPS, JKNQ में अंतर +1, +3, +3 है; FGIL में +1, +2, +3 है।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Digit Operations", "q": "Study the following series of digits and answer the question.\n6 9 8 2 2 3 4 4 6 7 5 4 3 4 4 5 7 9 3 3 4 6 1 7 6\nHow many even digits are there, each of which is immediately preceded by an odd digit AND immediately followed by a digit greater than 5?", "o": ["2", "3", "4", "1"], "a": 3, "e": "Matching groups: 3 4 6 → 1.", "qh": "नीचे दी गई अंकों की शृंखला पढ़कर प्रश्न का उत्तर दीजिए।\n6 9 8 2 2 3 4 4 6 7 5 4 3 4 4 5 7 9 3 3 4 6 1 7 6\nऐसे कितने सम अंक हैं, जिनके ठीक पहले विषम अंक हो और ठीक बाद 5 से बड़ा अंक हो?", "oh": ["2", "3", "4", "1"], "eh": "शर्त पूरी करने वाले समूह: 3 4 6 → 1।", "level": "tough"}, {"s": "General Intelligence and Reasoning", "t": "Syllogism", "q": "Read the given statements and conclusions carefully. Assuming that the information given in the statements is true, even if it appears to be at variance with commonly known facts, decide which of the given conclusions logically follow(s) from the statements.\nStatements:\nSome lamps are plates.\nAll plates are tables.\nConclusions:\nI. Some plates are not tables.\nII. No lamps are plates.", "o": ["Only conclusion I follows", "Neither I nor II follows", "Only conclusion II follows", "Both I and II follow"], "a": 1, "e": "Each conclusion fails in at least one possible diagram, and they do not form an either–or pair.", "qh": "दिए गए कथनों और निष्कर्षों को ध्यान से पढ़िए। कथनों को सही मानते हुए, भले ही वे आम जानकारी से अलग लगें, तय कीजिए कि कौन-सा/से निष्कर्ष कथनों से तर्क के आधार पर निकलता/निकलते है/हैं।\nकथन:\nकुछ लैंप प्लेटें हैं।\nसभी प्लेटें मेज़ें हैं।\nनिष्कर्ष:\nI. कुछ प्लेटें मेज़ें नहीं हैं।\nII. कोई भी लैंप प्लेटें नहीं है।", "oh": ["केवल निष्कर्ष I सही है", "न I सही है, न II", "केवल निष्कर्ष II सही है", "I और II दोनों सही हैं"], "eh": "हर निष्कर्ष किसी न किसी आरेख में गलत हो जाता है, और ये 'या तो–या' वाली जोड़ी नहीं हैं।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Symbol Series", "q": "Study the following arrangement carefully and answer the question.\n$ € 2 J 5 2 Q S 9 & + © 8 # Q £ 1 5 @ % # F\nHow many letters are there in the arrangement, each of which is immediately followed by a number but NOT immediately preceded by a symbol?", "o": ["1", "2", "3", "4"], "a": 1, "e": "Matching places: 2J5, QS9 → 2.", "qh": "नीचे दिए गए क्रम को ध्यान से पढ़कर प्रश्न का उत्तर दीजिए।\n$ € 2 J 5 2 Q S 9 & + © 8 # Q £ 1 5 @ % # F\nइस क्रम में ऐसे कितने अक्षर हैं, जिनके ठीक बाद एक संख्या है, पर ठीक पहले चिह्न नहीं है?", "oh": ["1", "2", "3", "4"], "eh": "शर्त पूरी करने वाले स्थान: 2J5, QS9 → 2।", "level": "tough"}, {"s": "General Intelligence and Reasoning", "t": "Seating Arrangement", "q": "D, J, R, Q and L are sitting around a circular table, all facing the centre.\nL sits immediately to the right of R.\nQ sits immediately to the left of J.\nJ is an immediate neighbour of Q.\nJ sits immediately to the left of R.\nWho sits to the immediate right of Q?", "o": ["D", "R", "L", "J"], "a": 3, "e": "Only one arrangement fits. Going to the right (anticlockwise) from Q: Q → J → R → L → D. Answer: J.", "qh": "D, J, R, Q और L एक गोल मेज़ के चारों ओर केंद्र की ओर मुँह करके बैठे हैं।\nL, R के ठीक दाईं ओर बैठा है।\nQ, J के ठीक बाईं ओर बैठा है।\nJ, Q का ठीक पड़ोसी है।\nJ, R के ठीक बाईं ओर बैठा है।\nQ के ठीक दाईं ओर कौन बैठा है?", "oh": ["D", "R", "L", "J"], "eh": "केवल एक व्यवस्था बैठती है। Q से दाईं ओर (घड़ी की उलटी दिशा में) चलें: Q → J → R → L → D। उत्तर: J।", "level": "easy"}]});
